WITH m AS (SELECT DISTINCT capture_id, mob_id FROM bestiary_fights WHERE zone_id = {zone:Int64} AND mob_name = {name:String} AND capture_id NOT IN (SELECT capture_id FROM capture_trust FINAL WHERE trust = 'flagged')), r AS (SELECT capture_id, idx, value FROM action_results WHERE message IN (162, 225, 228, 275, 366) AND value > 0 AND (capture_id, target_id) IN (SELECT capture_id, mob_id FROM m) AND NOT (bitShiftRight(actor_id, 24) = 1 AND bitAnd(actor_id, 4095) < 1024)), a AS (SELECT capture_id, idx FROM actions WHERE resend AND (capture_id, idx) IN (SELECT capture_id, idx FROM r)) SELECT count() AS n, max(r.value) AS most, argMax(concat('https://lens.sruon.dev/c/', r.capture_id, '#packet=', toString(r.idx)), r.value) AS lens_url FROM r WHERE (r.capture_id, r.idx) NOT IN (SELECT capture_id, idx FROM a)
